    "short_description_english": "A reliable 3.5-month white samba variety specifically developed for dry zone conditions with good disease resistance.",
    "short_description_sinhala": "\u0dc0\u0dd2\u0dba\u0dc5\u0dd2 \u0d9a\u0dbd\u0dcf\u0db4 \u0dad\u0dad\u0dca\u0dad\u0dca\u0dc0 \u0dc3\u0db3\u0dc4\u0dcf \u0dc0\u0dd2\u0dc1\u0dda\u0dc2\u0dba\u0dd9\u0db1\u0dca \u0db1\u0dd2\u0dbb\u0dca\u0db8\u0dcf\u0dab\u0dba \u0d9a\u0dc5, \u0dc4\u0ddc\u0db3 \u0dbb\u0ddd\u0d9c \u0db4\u0dca\u200d\u0dbb\u0dad\u0dd2\u0dbb\u0ddd\u0db0\u0dba \u0dc3\u0dc4\u0dd2\u0dad \u0db8\u0dcf\u0dc3 3.5 \u0d9a \u0dc3\u0dd4\u0daf\u0dd4 \u0dc3\u0db9\u0dcf \u0db4\u0dca\u200d\u0dbb\u0db7\u0dda\u0daf\u0dba\u0d9a\u0dd2.",
    "farmer_recommendation": "Best suited for Dry Zone. Ensure adequate water supply during panicle initiation stage.",
    "farmer_recommendation_sinhala": "\u0dc0\u0dd2\u0dba\u0dc5\u0dd2 \u0d9a\u0dbd\u0dcf\u0db4\u0dba\u0da7 \u0dc0\u0da9\u0dcf\u0dad\u0dca \u0d9c\u0dd0\u0dbd\u0db4\u0dda. \u0db4\u0dd2\u0dc5\u0d9a\u0dba \u0d86\u0dbb\u0db8\u0dca\u0db7 \u0dc0\u0db1 \u0d85\u0dc0\u0dc3\u0dca\u0dae\u0dcf\u0dc0\u0dda \u0db4\u0dca\u200d\u0dbb\u0db8\u0dcf\u0dab\u0dc0\u0dad\u0dca \u0da2\u0dbd \u0dc3\u0dd0\u0db4\u0dba\u0dd4\u0db8\u0d9a\u0dca \u0dc3\u0dc4\u0dad\u0dd2\u0d9a \u0d9a\u0dbb\u0db1\u0dca\u0db1.",
