    "farmer_recommendation_sinhala": "\u0d9a\u0db1\u0dca\u0db1 \u0daf\u0dd9\u0d9a\u0dd9\u0dc4\u0dd2\u0db8 \u0dbb\u0ddd\u0db4\u0dab\u0dba \u0dc3\u0db3\u0dc4\u0dcf \u0dc3\u0dd4\u0daf\u0dd4\u0dc3\u0dd4\u0dba. \u0dc4\u0ddc\u0db3\u0db8 \u0db4\u0dca\u200d\u0dbb\u0dad\u0dd2\u0db5\u0dbd \u0dc3\u0db3\u0dc4\u0dcf \u0dc3\u0dc4\u0dad\u0dd2\u0d9a \u0dbd\u0dad\u0dca \u0db6\u0dd3\u0da2 \u0db7\u0dcf\u0dc0\u0dd2\u0dad \u0d9a\u0dbb\u0db1\u0dca\u0db1.",
