    "short_description_english": "An outstanding 3.5-month variety with exceptional blast resistance, ideal for blast-prone farming areas in the dry zone.",
    "short_description_sinhala": "\u0d9a\u0dd4\u0dc2\u0dca\u0da8 \u0dc0\u0dca\u200d\u0dba\u0dcf\u0db4\u0dca\u0dad \u0d9c\u0ddc\u0dc0\u0dd2\u0d9a\u0dbb\u0dd4 \u0db4\u0dca\u200d\u0dbb\u0daf\u0dda\u0dc1 \u0dc3\u0db3\u0dc4\u0dcf \u0d89\u0dad\u0dcf \u0dba\u0ddd\u0d9c\u0dca\u200d\u0dba, \u0dc3\u0dd4\u0dc0\u0dd2\u0dc1\u0dda\u0dc2 \u0d9a\u0dd4\u0dc2\u0dca\u0da8 \u0db4\u0dca\u200d\u0dbb\u0dad\u0dd2\u0dbb\u0ddd\u0db0\u0dba \u0dc3\u0dc4\u0dd2\u0dad \u0dc0\u0dd2\u0dc1\u0dd2\u0dc2\u0dca\u0da7 \u0db8\u0dcf\u0dc3 3.5 \u0d9a \u0db4\u0dca\u200d\u0dbb\u0db7\u0dda\u0daf\u0dba\u0d9a\u0dd2.",
    "farmer_recommendation": "Recommended for high blast-risk areas. No fungicide needed for blast if grown correctly.",
    "farmer_recommendation_sinhala": "\u0d89\u0dc4\u0dc5 \u0d9a\u0dd4\u0dc2\u0dca\u0da8 \u0d85\u0dc0\u0daf\u0dcf\u0db1\u0db8\u0dca \u0db4\u0dca\u200d\u0dbb\u0daf\u0dda\u0dc1 \u0dc3\u0db3\u0dc4\u0dcf \u0db1\u0dd2\u0dbb\u0dca\u0daf\u0dda\u0dc1 \u0d9a\u0dd9\u0dbb\u0dda. \u0db1\u0dd2\u0dc0\u0dd0\u0dbb\u0daf\u0dd2\u0dc0 \u0dc0\u0d9c\u0dcf \u0d9a\u0dc5\u0dc4\u0ddc\u0dad\u0dca \u0d9a\u0dd4\u0dc2\u0dca\u0da8 \u0dc3\u0db3\u0dc4\u0dcf \u0daf\u0dd2\u0dbd\u0dd3\u0dbb \u0db1\u0dcf\u0dc1\u0d9a \u0d85\u0dc0\u0dc1\u0dca\u200d\u0dba \u0db1\u0ddc\u0dc0\u0dda.",
