    "farmer_recommendation": "Plant only in Maha season with assured irrigation. High fertilizer input required for maximum yield.",
    "farmer_recommendation_sinhala": "\u0db1\u0dd2\u0dc1\u0dca\u0da0\u0dd2\u0dad \u0dc0\u0dcf\u0dbb\u0dd2\u0da2\u0dbd\u0dba \u0dc3\u0dc4\u0dd2\u0dad\u0dc0 \u0db8\u0dc4 \u0d9a\u0db1\u0dca\u0db1\u0dba\u0dda \u0db4\u0db8\u0dab\u0d9a\u0dca \u0dbb\u0ddd\u0db4\u0dab\u0dba \u0d9a\u0dbb\u0db1\u0dca\u0db1. \u0db4\u0dca\u200d\u0dbb\u0dc1\u0dc3\u0dca\u0dad \u0d85\u0dc3\u0dca\u0dc0\u0dd0\u0db1\u0dca\u0db1\u0d9a\u0dca \u0dc3\u0db3\u0dc4\u0dcf \u0d89\u0dc4\u0dc5 \u0db4\u0ddc\u0dc4\u0ddc\u0dbb \u0d86\u0daf\u0dcf\u0db1\u0dba \u0d85\u0dc0\u0dc1\u0dca\u200d\u0dba \u0dc0\u0dda.",
