    "short_description_english": "The latest high-yield release from RRDI Batalagoda combining superior disease resistance with excellent grain quality. Best for modern commercial farming.",
    "short_description_sinhala": "\u0dc0\u0dd2\u0dc1\u0dd2\u0dc2\u0dca\u0da7 \u0dbb\u0ddd\u0d9c \u0db4\u0dca\u200d\u0dbb\u0dad\u0dd2\u0dbb\u0ddd\u0db0\u0dba \u0dc3\u0dc4 \u0dc0\u0dd2\u0dc1\u0dd2\u0dc2\u0dca\u0da7 \u0db0\u0dcf\u0db1\u0dca\u200d\u0dba \u0d9c\u0dd4\u0dab\u0dcf\u0dad\u0dca\u0db8\u0d9a\u0db7\u0dcf\u0dc0\u0dba \u0d92\u0d9a\u0dcf\u0db6\u0daf\u0dca\u0db0 RRDI \u0db6\u0dad\u0dbd\u0d9c\u0ddc\u0da9 \u0db1\u0dc0\u0dad\u0db8 \u0d89\u0dc4\u0dc5-\u0d85\u0dc3\u0dca\u0dc0\u0dd0\u0db1\u0dca\u0db1\u0dda \u0db1\u0dd2\u0d9a\u0dd4\u0dad\u0dd4\u0dc0. \u0db1\u0dd6\u0dad\u0db1 \u0dc0\u0dcf\u0dab\u0dd2\u0da2 \u0d9c\u0ddc\u0dc0\u0dd2\u0dad\u0dd0\u0db1\u0da7 \u0dc4\u0ddc\u0db3\u0db8.",
    "farmer_recommendation": "New variety - follow DOA guidelines strictly for best results. Ideal replacement for Bg352.",
    "farmer_recommendation_sinhala": "\u0db1\u0dc0 \u0db4\u0dca\u200d\u0dbb\u0db7\u0dda\u0daf\u0dba - \u0dc4\u0ddc\u0db3\u0db8 \u0db4\u0dca\u200d\u0dbb\u0dad\u0dd2\u0db5\u0dbd \u0dc3\u0db3\u0dc4\u0dcf DOA \u0db8\u0dcf\u0dbb\u0dca\u0d9c\u0ddd\u0db4\u0daf\u0dda\u0dc1 \u0daf\u0dd0\u0da9\u0dd2 \u0dbd\u0dd9\u0dc3 \u0d85\u0db1\u0dd4\u0d9c\u0db8\u0db1\u0dba \u0d9a\u0dbb\u0db1\u0dca\u0db1. Bg352 \u0da7 \u0d89\u0dad\u0dcf \u0d9c\u0dd0\u0dbd\u0db4\u0dd9\u0db1 \u0d86\u0daf\u0dda\u0dc1\u0d9a\u0dba\u0d9a\u0dd2.",
    "official_source": "Department of Agriculture Sri Lanka",
