    "short_description_english": "Specifically bred for iron-toxic, waterlogged wet zone soils. Tolerates high-rainfall conditions common in Kalutara, Galle, and Matara districts.",
    "short_description_sinhala": "\u0dba\u0d9a\u0da9-\u0dc0\u0dd2\u0dc2 \u0dc3\u0dc4\u0dd2\u0dad, \u0da2\u0dbd\u0d9c\u0dd0\u0dbd\u0dd9\u0db1 \u0dad\u0dd9\u0dad\u0dca \u0d9a\u0dbd\u0dcf\u0db4 \u0d9c\u0ddc\u0da9\u0dd9\u0dc0 \u0dc3\u0db3\u0dc4\u0dcf \u0dc0\u0dd2\u0dc1\u0dda\u0dc2\u0dba\u0dd9\u0db1\u0dca \u0db6\u0dd9\u0daf\u0dcf \u0d9c\u0db1\u0dca\u0db1\u0dcf \u0dbd\u0daf\u0dd3. \u0d9a\u0dc5\u0dd4\u0dad\u0dbb, \u0d9c\u0dcf\u0dbd\u0dca\u0dbd \u0dc3\u0dc4 \u0db8\u0dcf\u0dad\u0dbb \u0daf\u0dd2\u0dc3\u0dca\u0dad\u0dca\u200d\u0dbb\u0dd2\u0d9a\u0dca\u0d9a\u0dc0\u0dbd \u0dc3\u0dcf\u0db8\u0dcf\u0db1\u0dca\u200d\u0dba \u0d89\u0dc4\u0dc5-\u0dc0\u0dbb\u0dca\u0dc2\u0dcf\u0dc0 \u0d89\u0dc0\u0dc3\u0dd3\u0db8.",
    "farmer_recommendation": "Best for low-lying, poorly-drained areas with iron-toxic soils in the wet zone.",
    "farmer_recommendation_sinhala": "\u0dad\u0dd9\u0dad\u0dca \u0d9a\u0dbd\u0dcf\u0db4\u0dba\u0dda \u0dba\u0d9a\u0da9-\u0dc0\u0dd2\u0dc2 \u0d9c\u0ddc\u0da9\u0dd9\u0dc0 \u0d87\u0dad\u0dd2, \u0da2\u0dbd\u0dcf\u0db4\u0dc0\u0dcf\u0dc4\u0db1\u0dba \u0db1\u0dd2\u0dc3\u0dd2\u0dbd\u0dd9\u0dc3 \u0db1\u0ddc\u0dc3\u0dd2\u0daf\u0dd4\u0dc0\u0db1, \u0db4\u0dc4\u0dad\u0dca \u0db4\u0dca\u200d\u0dbb\u0daf\u0dda\u0dc1 \u0dc3\u0db3\u0dc4\u0dcf \u0dc4\u0ddc\u0db3\u0db8.",
