    "short_description_english": "The premium long-grain variety of the BW series. Maximum yield and quality for wet zone Maha season under good management.",
    "short_description_sinhala": "BW \u0dc1\u0dca\u200d\u0dbb\u0dda\u0dab\u0dd2\u0dba \u0db4\u0dca\u200d\u0dbb\u0dd2\u0db8\u0dd2\u0dba\u0db8\u0dca \u0daf\u0dd2\u0d9c\u0dd4-\u0db0\u0dcf\u0db1\u0dca\u200d\u0dba \u0db4\u0dca\u200d\u0dbb\u0db7\u0dda\u0daf\u0dba. \u0dc4\u0ddc\u0db3 \u0d9a\u0dc5\u0db8\u0db1\u0dcf\u0d9a\u0dbb\u0dab\u0dba \u0dba\u0da7\u0dad\u0dda \u0dad\u0dd9\u0dad\u0dca \u0d9a\u0dbd\u0dcf\u0db4 \u0db8\u0dc4 \u0d9a\u0db1\u0dca\u0db1\u0dba \u0dc3\u0db3\u0dc4\u0dcf \u0d8b\u0db4\u0dbb\u0dd2\u0db8 \u0d85\u0dc3\u0dca\u0dc0\u0dd0\u0db1\u0dca\u0db1\u0d9a\u0dca \u0dc3\u0dc4 \u0d9c\u0dd4\u0dab\u0dcf\u0dad\u0dca\u0db8\u0d9a\u0db7\u0dcf\u0dc0\u0dba.",
    "farmer_recommendation": "Plant only in Maha season. Ensure consistent water supply throughout growing period.",
    "farmer_recommendation_sinhala": "\u0db8\u0dc4 \u0d9a\u0db1\u0dca\u0db1\u0dba\u0dda \u0db4\u0db8\u0dab\u0d9a\u0dca \u0dbb\u0ddd\u0db4\u0dab\u0dba \u0d9a\u0dbb\u0db1\u0dca\u0db1. \u0dc0\u0dbb\u0dca\u0db0\u0db1 \u0d9a\u0dcf\u0dbd\u0dba \u0db4\u0dd4\u0dbb\u0dcf \u0dc3\u0dca\u0dae\u0dcf\u0dc0\u0dbb \u0da2\u0dbd \u0dc3\u0dd0\u0db4\u0dba\u0dd4\u0db8\u0d9a\u0dca \u0dc3\u0dc4\u0dad\u0dd2\u0d9a \u0d9a\u0dbb\u0db1\u0dca\u0db1.",
