    "short_description_english": "A red kakulu variety from Labuduwa Research Station suited for wet zone cultivation with good flood and disease tolerance.",
    "short_description_sinhala": "\u0dc4\u0ddc\u0db3 \u0d9c\u0d82\u0dc0\u0dad\u0dd4\u0dbb \u0dc3\u0dc4 \u0dbb\u0ddd\u0d9c \u0d89\u0dc0\u0dc3\u0dd2\u0dbd\u0dd2\u0dc0\u0db1\u0dca\u0dad \u0dc3\u0dc4\u0dd2\u0dad \u0dad\u0dd9\u0dad\u0dca \u0d9a\u0dbd\u0dcf\u0db4 \u0dc0\u0d9c\u0dcf\u0dc0 \u0dc3\u0db3\u0dc4\u0dcf \u0d9c\u0dd0\u0dbd\u0db4\u0dd9\u0db1 \u0dbd\u0db6\u0dd4\u0daf\u0dd6\u0dc0 \u0db4\u0dbb\u0dca\u0dba\u0dda\u0dc2\u0dab \u0db8\u0db0\u0dca\u200d\u0dba\u0dc3\u0dca\u0dae\u0dcf\u0db1\u0dba\u0dda \u0dbb\u0dad\u0dd4 \u0d9a\u0dcf\u0d9a\u0dd4\u0dbd\u0dd4 \u0db4\u0dca\u200d\u0dbb\u0db7\u0dda\u0daf\u0dba\u0d9a\u0dd2.",
    "farmer_recommendation": "Suitable for flood-prone areas in southern wet zone. Harvest promptly to avoid grain shedding.",
    "farmer_recommendation_sinhala": "\u0daf\u0d9a\u0dd4\u0dab\u0dd4 \u0dad\u0dd9\u0dad\u0dca \u0d9a\u0dbd\u0dcf\u0db4\u0dba\u0dda \u0d9c\u0d82\u0dc0\u0dad\u0dd4\u0dbb\u0da7 \u0d9c\u0ddc\u0daf\u0dd4\u0dbb\u0dd4 \u0db4\u0dca\u200d\u0dbb\u0daf\u0dda\u0dc1 \u0dc3\u0db3\u0dc4\u0dcf \u0dc3\u0dd4\u0daf\u0dd4\u0dc3\u0dd4\u0dba. \u0db0\u0dcf\u0db1\u0dca\u200d\u0dba \u0dc4\u0dd9\u0dc5\u0dd3\u0db8 \u0dc0\u0dc5\u0d9a\u0dca\u0dc0\u0dcf \u0d9c\u0dd0\u0db1\u0dd3\u0db8\u0da7 \u0d89\u0d9a\u0dca\u0db8\u0db1\u0dd2\u0db1\u0dca \u0d85\u0dc3\u0dca\u0dc0\u0db1\u0dd4 \u0db1\u0dd9\u0dc5\u0dcf \u0d9c\u0db1\u0dca\u0db1.",
