    "best_for": {
      "english": "Dry Zone Red Rice Production",
      "sinhala": "\u0dc0\u0dd2\u0dba\u0dc5\u0dd2 \u0d9a\u0dbd\u0dcf\u0db4 \u0dbb\u0dad\u0dd4 \u0dc3\u0dc4\u0dbd\u0dca \u0db1\u0dd2\u0dc2\u0dca\u0db4\u0dcf\u0daf\u0db1\u0dba"
    },
    "advantages": [
      "Drought tolerant red rice",
      "Low water requirement",
      "Good nutritional value"
    ],
    "advantages_sinhala": [
      "\u0db1\u0dd2\u0dba\u0d82 \u0d89\u0dc0\u0dc3\u0dd2\u0dbd\u0dd2\u0dc0\u0db1\u0dca\u0dad \u0dbb\u0dad\u0dd4 \u0dc3\u0dc4\u0dbd\u0dca",
      "\u0d85\u0da9\u0dd4 \u0da2\u0dbd \u0d85\u0dc0\u0dc1\u0dca\u200d\u0dba\u0dad\u0dcf",
      "\u0dc4\u0ddc\u0db3 \u0db4\u0ddd\u0dc2\u0dab \u0d85\u0d9c\u0dba"
    ],
    "limitations": [
      "Dry Zone only",
      "Lower yield than white varieties"
    ],
    "limitations_sinhala": [
      "\u0dc0\u0dd2\u0dba\u0dc5\u0dd2 \u0d9a\u0dbd\u0dcf\u0db4\u0dba \u0db4\u0db8\u0dab\u0dd2",
      "\u0dc3\u0dd4\u0daf\u0dd4 \u0db4\u0dca\u200d\u0dbb\u0db7\u0dda\u0daf\u0dc0\u0dbd\u0da7 \u0dc0\u0da9\u0dcf \u0d85\u0da9\u0dd4 \u0d85\u0dc3\u0dca\u0dc0\u0dd0\u0db1\u0dca\u0db1\u0d9a\u0dca"
    ],
    "short_description_english": "A drought-tolerant red kakulu variety from Ambalantota Research Station, ideal for dry zone farmers seeking nutritious red rice.",
    "short_description_sinhala": "\u0db1\u0dd2\u0dba\u0d82 \u0d89\u0dc0\u0dc3\u0dd2\u0dbd\u0dd2\u0dc0\u0db1\u0dca\u0dad \u0dbb\u0dad\u0dd4 \u0d9a\u0dcf\u0d9a\u0dd4\u0dbd\u0dd4 \u0db4\u0dca\u200d\u0dbb\u0db7\u0dda\u0daf\u0dba\u0d9a\u0dca \u0d85\u0db8\u0dca\u0db6\u0dbd\u0db1\u0dca\u0dad\u0ddc\u0da7 \u0db4\u0dbb\u0dca\u0dba\u0dda\u0dc2\u0dab \u0db8\u0db0\u0dca\u200d\u0dba\u0dc3\u0dca\u0dae\u0dcf\u0db1\u0dba\u0dd9\u0db1\u0dca, \u0db4\u0ddd\u0dc2\u0dca\u200d\u0dba\u0daf\u0dcf\u0dba\u0dd3 \u0dbb\u0dad\u0dd4 \u0dc3\u0dc4\u0dbd\u0dca \u0dc3\u0dd9\u0dc0\u0dd6 \u0dc0\u0dd2\u0dba\u0dc5\u0dd2 \u0d9a\u0dbd\u0dcf\u0db4 \u0d9c\u0ddc\u0dc0\u0dd3\u0db1\u0dca \u0dc3\u0db3\u0dc4\u0dcf \u0d89\u0dad\u0dcf \u0d9c\u0dd0\u0dbd\u0db4\u0dda.",
    "farmer_recommendation": "Excellent for Hambantota and Monaragala. Low irrigation requirement saves cost.",
    "farmer_recommendation_sinhala": "\u0dc4\u0db8\u0dca\u0db6\u0db1\u0dca\u0dad\u0ddc\u0da7 \u0dc3\u0dc4 \u0db8\u0ddc\u0db1\u0dbb\u0dcf\u0d9c\u0dbd \u0dc3\u0db3\u0dc4\u0dcf \u0dc0\u0dd2\u0dc1\u0dd2\u0dc2\u0dca\u0da7\u0dba. \u0d85\u0da9\u0dd4 \u0dc0\u0dcf\u0dbb\u0dd2\u0da2\u0dbd \u0d85\u0dc0\u0dc1\u0dca\u200d\u0dba\u0dad\u0dcf \u0db4\u0dd2\u0dbb\u0dd2\u0dc0\u0dd0\u0dba \u0d89\u0dad\u0dd2\u0dbb\u0dd2 \u0d9a\u0dbb\u0dba\u0dd2.",
