      "\u0dc0\u0da9\u0dcf\u0dad\u0dca \u0da2\u0db1\u0db4\u0dca\u200d\u0dbb\u0dd2\u0dba AT \u0db4\u0dca\u200d\u0dbb\u0db7\u0dda\u0daf\u0dba",
