    "short_description_english": "An ancient heritage paddy variety with exceptional medicinal properties. Cultivated by traditional farmers for millennia in the dry zone.",
    "short_description_sinhala": "\u0dc3\u0dd4\u0dc0\u0dd2\u0dc1\u0dda\u0dc2 \u0d96\u0dc2\u0db0\u0dd3\u0dba \u0d9c\u0dd4\u0dab \u0dc3\u0dc4\u0dd2\u0dad \u0db4\u0dd0\u0dbb\u0dab\u0dd2 \u0d8b\u0dbb\u0dd4\u0db8 \u0dc1\u0dca\u200d\u0dbb\u0dd3 \u0dbd\u0dcf\u0d82\u0d9a\u0dd3\u0dba \u0da2\u0dcf\u0dad\u0dd2\u0d9a\u0dbd\u0dcf\u0dbd \u0dd2\u0dc0\u0dd2\u0d9a\u0da7\u0dca \u0db4\u0dca\u200d\u0dbb\u0db7\u0dda\u0daf\u0dba\u0d9a\u0dd2. \u0dc3\u0dc4\u0dc1\u0dca\u200d\u0dbb\u0dc0\u0dbb\u0dca\u0dc2 \u0d9c\u0dab\u0db1\u0dcf\u0dc0\u0d9a\u0dca \u0db4\u0dd4\u0dbb\u0dcf \u0dc3\u0dcf\u0db8\u0dca\u0db4\u0dca\u200d\u0dbb\u0daf\u0dcf\u0dba\u0dd2\u0d9a \u0d9c\u0ddc\u0dc0\u0dd3\u0db1\u0dca \u0dc0\u0dd2\u0dc3\u0dd2\u0db1\u0dca \u0dc0\u0dd2\u0dba\u0dc5\u0dd2 \u0d9a\u0dbd\u0dcf\u0db4\u0dba\u0dda \u0dc0\u0d9c\u0dcf \u0d9a\u0dd9\u0dbb\u0dda.",
    "farmer_recommendation": "Best for organic farming with premium market access. Requires no chemical fertilizer or pesticide.",
    "farmer_recommendation_sinhala": "\u0db4\u0dca\u200d\u0dbb\u0dd2\u0db8\u0dd2\u0dba\u0db8\u0dca \u0dc0\u0dd9\u0dc5\u0db3 \u0db4\u0dca\u200d\u0dbb\u0dc0\u0dda\u0dc1\u0dba \u0dc3\u0dc4\u0dd2\u0dad \u0da2\u0ddb\u0dc0 \u0d9c\u0ddc\u0dc0\u0dd2\u0dad\u0dd0\u0db1\u0da7 \u0dc4\u0ddc\u0db3\u0db8. \u0dbb\u0dc3\u0dcf\u0dba\u0db1\u0dd2\u0d9a \u0db4\u0ddc\u0dc4\u0ddc\u0dbb \u0dc4\u0ddd \u0db4\u0dc5\u0dd2\u0db6\u0ddd\u0db0 \u0db1\u0dcf\u0dc1\u0d9a \u0d85\u0dc0\u0dc1\u0dca\u200d\u0dba \u0db1\u0ddc\u0dc0\u0dda.",
