    "short_description_english": "Sri Lanka's most prized heritage rice. The naturally aromatic Suwandel is a royal rice variety historically served to royalty. Commands the highest premium market price.",
    "short_description_sinhala": "\u0dc1\u0dca\u200d\u0dbb\u0dd3 \u0dbd\u0d82\u0d9a\u0dcf\u0dc0\u0dda \u0dc0\u0da9\u0dcf\u0dad\u0dca \u0dc1\u0dca\u200d\u0dbb\u0dda\u0dc2\u0dca\u0da8 \u0d8b\u0dbb\u0dd4\u0db8 \u0dc3\u0dc4\u0dbd. \u0dc3\u0dca\u0dc0\u0dcf\u0db7\u0dcf\u0dc0\u0dd2\u0d9a\u0dc0 \u0dc3\u0dd4\u0dc0\u0db3 \u0dc3\u0dc4\u0dd2\u0dad \u0dc3\u0dd4\u0dc0\u0db3\u0dd9\u0dbd\u0dca \u0d93\u0dad\u0dd2\u0dc4\u0dcf\u0dc3\u0dd2\u0d9a\u0dc0 \u0dbb\u0dcf\u0da2 \u0db4\u0dc0\u0dd4\u0dbd\u0da7 \u0dc3\u0dda\u0dc0\u0dba \u0d9a\u0dc5 \u0dbb\u0dcf\u0da2\u0d9a\u0dd3\u0dba \u0dc3\u0dc4\u0dbd\u0dca \u0db4\u0dca\u200d\u0dbb\u0db7\u0dda\u0daf\u0dba\u0d9a\u0dd2. \u0d89\u0dc4\u0dc5\u0db8 \u0db4\u0dca\u200d\u0dbb\u0dd2\u0db8\u0dd2\u0dba\u0db8\u0dca \u0dc0\u0dd9\u0dc5\u0db3 \u0db8\u0dd2\u0dbd\u0d9a\u0dca \u0dbd\u0db6\u0dcf \u0d9c\u0db1\u0dd3.",
    "farmer_recommendation": "Requires premium market access to be profitable. Best for organic certified farms. Store seeds carefully between seasons.",
    "farmer_recommendation_sinhala": "\u0dbd\u0dcf\u0db7\u0daf\u0dcf\u0dba\u0dd3 \u0dc0\u0dd3\u0db8\u0da7 \u0db4\u0dca\u200d\u0dbb\u0dd2\u0db8\u0dd2\u0dba\u0db8\u0dca \u0dc0\u0dd9\u0dc5\u0db3 \u0db4\u0dca\u200d\u0dbb\u0dc0\u0dda\u0dc1\u0dba \u0d85\u0dc0\u0dc1\u0dca\u200d\u0dba. \u0da2\u0ddb\u0dc0 \u0dc3\u0dc4\u0dad\u0dd2\u0d9a \u0dbd\u0dad\u0dca \u0d9c\u0ddc\u0dc0\u0dd2\u0dad\u0dd0\u0db1\u0da7 \u0dc4\u0ddc\u0db3\u0db8. \u0d9a\u0db1\u0dca\u0db1\u0dba \u0d85\u0dad\u0dbb \u0db6\u0dd3\u0da2 \u0db4\u0dca\u200d\u0dbb\u0dc0\u0dda\u0dc1\u0db8\u0dd9\u0db1\u0dca \u0d9c\u0db6\u0da9\u0dcf \u0d9a\u0dbb\u0db1\u0dca\u0db1.",
    "official_source": "Plant Genetic Resources Centre & Department of Agriculture Sri Lanka",
