    "farmer_recommendation": "Market through specialty organic and gourmet rice channels for maximum profitability.",
    "farmer_recommendation_sinhala": "\u0d8b\u0db4\u0dbb\u0dd2\u0db8 \u0dbd\u0dcf\u0db7\u0daf\u0dcf\u0dba\u0dd2\u0dad\u0dca\u0dc0\u0dba \u0dc3\u0db3\u0dc4\u0dcf \u0dc0\u0dd2\u0dc1\u0dda\u0dc2 \u0da2\u0ddb\u0dc0 \u0dc3\u0dc4 \u0d9c\u0dd6\u0dbb\u0dca\u0db8 \u0dc3\u0dc4\u0dbd\u0dca \u0db1\u0dcf\u0dbd\u0dd2\u0d9a\u0dcf \u0dc4\u0dbb\u0dc4\u0dcf \u0dc0\u0dd9\u0dc5\u0db3\u0dcf\u0db8\u0dca \u0d9a\u0dbb\u0db1\u0dca\u0db1.",
